import{_ as t,o,c as r,a}from"./chunks/plugin-vue_export-helper.B1AaF8Z1.js";const g=JSON.parse('{"title":"Лучшие промышленные практики построения AI-агентов, 7 из 10","description":"","frontmatter":{"site":"pro","title":"Лучшие промышленные практики построения AI-агентов, 7 из 10","date":"2026-10-09T00:00:00.000Z","source":"https://t.me/jfyi_ps/100","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/posts/2026-10-09-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-7"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Лучшие промышленные практики построения AI-агентов, 7 из 10"}],["meta",{"property":"og:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/posts/2026-10-09-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-7"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Лучшие промышленные практики построения AI-агентов, 7 из 10"}],["meta",{"name":"twitter:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BlogPosting\\",\\"headline\\":\\"Лучшие промышленные практики построения AI-агентов, 7 из 10\\",\\"description\\":\\"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы.\\",\\"url\\":\\"https://oleg-sidorkin.ru/posts/2026-10-09-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-7\\",\\"inLanguage\\":\\"ru-RU\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Oleg Sidorkin\\",\\"alternateName\\":\\"alterfo\\",\\"url\\":\\"https://oleg-sidorkin.ru\\",\\"jobTitle\\":\\"Software Engineer\\",\\"knowsAbout\\":[\\"Music\\",\\"Audio DSP\\",\\"AI\\",\\"RAG\\",\\"Frontend Development\\",\\"Solution Architecture\\"],\\"sameAs\\":[\\"https://github.com/alterfo\\"]},\\"datePublished\\":\\"2026-10-09\\"}"]]},"headers":[],"relativePath":"posts/2026-10-09-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-7.md","filePath":"posts/2026-10-09-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-7.md"}'),n={name:"posts/2026-10-09-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-7.md"};function i(s,e,p,l,c,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<p>Выжимка из книги Ли Боцзе «Глубокое понимание AI Agent: принципы проектирования и инженерная практика» (Pine AI, v2.0, 2026). **</p><h2 id="_7-оценка-агентов" tabindex="-1">7. Оценка агентов** <a class="header-anchor" href="#_7-оценка-агентов" aria-label="Permalink to &quot;7. Оценка агентов**&quot;">​</a></h2><p>Оценивай модель+Harness вместе. Model swap (фиксируй Harness, меняй модель) определяет, где узкое место; абляция (фиксируй модель, отключай компонент) — какой компонент важен.</p><p>Pass@k (хотя бы раз — потолок возможностей) vs Pass^k (все k подряд — бизнес-надёжность, резко ниже: p=0.6,k=5 → Pass@5≈99%, Pass^5≈7.8%). Для побочных эффектов используй песочницу/откат.</p><p>Среда оценки = 5 компонентов: датасет + состояние среды (явный сброс) + интерфейс инструментов (атомарный) + rubric + протокол взаимодействия. Моделируй границу знаний симулятора явно (постепенное раскрытие); требуй фактическое заземление.</p><p>Верификатор проверяет независимо подтверждаемые факты, не заявления агента. Для «исправление бага» — двойная проверка (упавший тест теперь проходит + прежние не сломаны). Включай задачи-ловушки с дезинформацией. Защита от утечки: комбинирование источников, параметризованные шаблоны, canary-метки. 3 источника набора: паблик-бенчмарки + бизнес-набор + возврат продакшн-траекторий (точнее всего).</p><p><strong>Rubric+LLM-as-Judge:</strong> экспертное знание + полнота с ловушками + вето для отклоняющих критериев + самодостаточность формулировок. Боритесь со смещением к длине. Мультиисточниковое судейство разными семействами моделей — иначе агент учится слепым зонам одного судьи.</p><p>Атрибуция отказа: структурированная запись (категория, первый шаг, доказательство, первопричина vs следствие); LLM помогает, человек обязателен. Отслеживай «сделал верно, доложил неверно» отдельно. Регрессия: сквозная + по префиксу траектории.</p><p>Выбор модели — TTFT/decode-скорость, стоимость на задачу, хвостовая p95. Статзначимость — парный анализ на одних задачах.</p><p>Наблюдаемость — стандартный протокол трассировки; превращай неудачные траектории в регрессионные тесты. От отчёта к улучшению: сначала проверь систему оценки, ищи кластеры отказов, меняй одну переменную за раунд.</p><p>Внутренняя инфраструктура: абляция функций с первого дня; A/B — многорукий тест, метрика механизма ≠ метрика цели, метрики-ограждения; feature flags (сборка/рантайм); промпт — детерминированный рендеринг+версии+регрессия как CI. Симуляционная среда для обучения требует reset и пропускной способности на порядки выше, чем для оценки.</p><p>Продолжение следует...</p>',12)])])}const u=t(n,[["render",i]]);export{g as __pageData,u as default};
